sys_script_include.script:
var BaseUtils = Class.create();
BaseUtils.prototype = {
    initialize: function () { },

    refQualBase: function () {
        var notTobeShown = [];
        var userStatus = current.state; 

        if (userStatus == 'Rejected') {
            return "sys_idIN"; 
        }

        var grRegistration = new GlideRecord("x_873666_bases_embedded_user_base_function");
        grRegistration.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4");
        grRegistration.query();

        while (grRegistration.next()) {
            notTobeShown.push(grRegistration.getValue("base_registration")); 
        }

        var grMaxCap = new GlideRecord("x_873666_bases_base_registration");
        grMaxCap.addQuery("max_capacity", ">", 0);
        grMaxCap.query();

        var basesComCapacidade = [];
        while (grMaxCap.next()) {
            basesComCapacidade.push(grMaxCap.getUniqueValue()); 
        }

        if (notTobeShown.length > 0 || basesComCapacidade.length === 0) {
            return "sys_idIN";
        }

        return "sys_idIN" + basesComCapacidade.join(",");
    },

    type: 'BaseUtils'
};
